template:
trait Render {
    fn render(&self) -> String;
}

struct Text(&'static str);
impl Render for Text {
    fn render(&self) -> String {
        self.0.into()
    }
}

fn render_all(items: &[⟦elem_ty⟧]) -> String {
    items.iter().map(|i| i.render()).collect()
}

fn main() {
    let items: Vec<Box<dyn Render>> = vec![
        ⟦item_expr⟧,
    ];
    println!("{}", render_all(&items));
}

tests:
#[test]
fn renders() {
    let items: Vec<Box<dyn Render>> = vec![Box::new(Text("hello"))];
    assert_eq!(render_all(&items), "hello");
}
